import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ATTENDANCE_TYPES = ['연차', '반차', '보상휴가', '병가', '예비군', '출장', '외근', '교육'];
const APPROVAL_STATUSES = ['신청', '마감', '마감 취소', '승인', '승인 취소', '반려'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function optionalText(value: unknown, label: string, maxLength: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > maxLength) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return value;
}

function wholeNumber(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr01801Controller {
  @Get('/attendance-requests')
  async listAttendanceRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const query = checks.queryOf(req.query);
    const attendanceType = optionalText(query['attendanceType'], '근태 유형', 20);
    const approvalStatus = optionalText(query['approvalStatus'], '승인 처리 상태', 20);
    if (attendanceType !== null && !ATTENDANCE_TYPES.includes(attendanceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 유형이 올바르지 않습니다.');
    }
    if (approvalStatus !== null && !APPROVAL_STATUSES.includes(approvalStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 처리 상태가 올바르지 않습니다.');
    }
    const page = wholeNumber(query['page'], 0, '쪽 번호');
    const size = Math.min(wholeNumber(query['size'], DEFAULT_SIZE, '쪽 크기') || DEFAULT_SIZE, MAX_SIZE);
    return transaction(async (db) => {
      const params = {
        attendanceType,
        approvalStatus,
        size,
        offset: page * size,
      };
      const where =
        'WHERE (CAST(:attendanceType AS text) IS NULL OR attendance_type = CAST(:attendanceType AS text)) ' +
        'AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))';
      const items = await db.query(
        'SELECT attendance_request_id AS "attendanceRequestId", ' +
          'attendance_type AS "attendanceType", ' +
          'start_date AS "startDate", ' +
          'end_date AS "endDate", ' +
          'reason AS "reason", ' +
          'changed_work_time AS "changedWorkTime", ' +
          'approval_status AS "approvalStatus" ' +
          'FROM attendance_request ' +
          where +
          ' ORDER BY attendance_request_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        params,
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM attendance_request ' + where,
        { attendanceType, approvalStatus },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/attendance-requests')
  @HttpCode(200)
  async createAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const data = checks.inputOf(req.body);
    const attendanceType = optionalText(data['attendanceType'], '근태 유형', 20);
    const startDate = optionalText(data['startDate'], '시작일', 10);
    const endDate = optionalText(data['endDate'], '종료일', 10);
    const reason = optionalText(data['reason'], '사유', 1000);
    const changedWorkTime = optionalText(data['changedWorkTime'], '변경 근무시간', 100);
    if (attendanceType === null || startDate === null || endDate === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 유형, 시작일, 종료일은 반드시 입력해야 합니다.');
    }
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해야 합니다.');
    }
    if (!ATTENDANCE_TYPES.includes(attendanceType)) {
      throw new ApiError(422, 'ATTENDANCE_VALIDATION_FAILED', '사용할 수 없는 근태 유형입니다.');
    }
    return transaction(async (db) => {
      const params = { userId: user.id, startDate, endDate };
      const employee = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (employee.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '신청자 정보를 찾을 수 없습니다.');
      }
      const order = await db.query(
        'SELECT (CAST(:endDate AS date) >= CAST(:startDate AS date)) AS "ok"',
        { startDate, endDate },
      );
      if (order[0]['ok'] !== true) {
        throw new ApiError(422, 'ATTENDANCE_VALIDATION_FAILED', '종료일은 시작일보다 빠를 수 없습니다.');
      }
      // 가정: 마감 기간 테이블이 없어 본인의 '마감' 상태 신청과 기간이 겹치면 마감된 기간으로 본다.
      const closed = await db.query(
        'SELECT attendance_request_id FROM attendance_request ' +
          "WHERE employee_id = CAST(:userId AS bigint) AND approval_status = '마감' " +
          'AND start_date <= CAST(:endDate AS date) AND end_date >= CAST(:startDate AS date)',
        params,
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'ATTENDANCE_PERIOD_CLOSED', '마감된 기간에는 근태를 신청할 수 없습니다. 마감 취소 후 다시 신청해 주세요.');
      }
      const rows = await db.query(
        'INSERT INTO attendance_request (employee_id, attendance_type, start_date, end_date, reason, changed_work_time, approval_status, created_at, updated_at) ' +
          "VALUES (CAST(:userId AS bigint), :attendanceType, CAST(:startDate AS date), CAST(:endDate AS date), :reason, :changedWorkTime, '신청', now(), now()) " +
          'RETURNING attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus"',
        { userId: user.id, attendanceType, startDate, endDate, reason, changedWorkTime },
      );
      return rows[0];
    });
  }

  @Post('/attendance-requests/:attendanceRequestId/cancel')
  @HttpCode(200)
  async cancelAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const attendanceRequestId = req.params['attendanceRequestId'];
    if (typeof attendanceRequestId !== 'string' || !/^\d+$/.test(attendanceRequestId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus" ' +
          'FROM attendance_request WHERE attendance_request_id = CAST(:id AS bigint)',
        { id: attendanceRequestId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '근태 신청을 찾을 수 없습니다.');
      }
      const current = rows[0];
      if (current['approvalStatus'] === '승인') {
        throw new ApiError(409, 'ATTENDANCE_REQUEST_APPROVED', '승인된 신청은 직접 취소할 수 없습니다. 승인 취소 절차를 진행해 주세요.');
      }
      if (current['approvalStatus'] === '마감') {
        throw new ApiError(409, 'ATTENDANCE_PERIOD_CLOSED', '마감된 기간의 신청은 취소할 수 없습니다. 마감 취소 후 진행해 주세요.');
      }
      // 가정: 전환표가 없어 '신청' 상태에서만 취소할 수 있다.
      if (current['approvalStatus'] !== '신청') {
        throw new ApiError(409, 'INVALID_STATE', '현재 상태에서는 취소할 수 없습니다.');
      }
      // 가정: 변경 구분은 '취소'로 기록한다.
      await db.execute(
        'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at) ' +
          "VALUES (CAST(:userId AS bigint), 'attendance_request', CAST(:id AS bigint), '취소', now(), '근태 신청 취소', now(), now())",
        { userId: user.id, id: attendanceRequestId },
      );
      return current;
    });
  }
}

