import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['연차', '연차'],
  ['반차', '반차'],
  ['보상휴가', '보상휴가'],
  ['병가', '병가'],
  ['예비군', '예비군'],
  ['출장', '출장'],
  ['외근', '외근'],
  ['교육', '교육'],
];

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감 취소', '마감 취소'],
  ['승인', '승인'],
  ['승인 취소', '승인 취소'],
  ['반려', '반려'],
];

const SIZE = 20;

export default function FnSfr01801Page({ role, notify }: PageProps) {
  const [typeFilter, setTypeFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [attendanceType, setAttendanceType] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [reason, setReason] = useState('');
  const [changedWorkTime, setChangedWorkTime] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ attendanceType: typeFilter, approvalStatus: statusFilter });
  }

  function reset() {
    setTypeFilter('');
    setStatusFilter('');
    setPage(0);
    setApplied({});
  }

  function openCreate() {
    setAttendanceType('');
    setStartDate('');
    setEndDate('');
    setReason('');
    setChangedWorkTime('');
    setCreating(true);
  }

  async function submitCreate() {
    if (!attendanceType || !startDate || !endDate) {
      throw new Error('근태 유형, 시작일, 종료일을 입력해 주세요.');
    }
    if (endDate < startDate) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    await call('POST', '/attendance-requests', role, {
      attendanceType,
      startDate,
      endDate,
      reason,
      changedWorkTime,
    });
    notify('근태를 신청했습니다.');
    setCreating(false);
    reload();
  }

  async function submitCancel() {
    if (!selected) {
      return;
    }
    await call('POST', '/attendance-requests/' + String(selected['attendanceRequestId']) + '/cancel', role, {});
    notify('근태 신청을 취소했습니다.');
    setCancelling(false);
    setSelected(null);
    reload();
  }

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>근태 신청 내용</h2>
          <Pairs
            items={[
              ['근태 유형', String(selected['attendanceType'] ?? '')],
              ['시작일', <DateText value={selected['startDate']} />],
              ['종료일', <DateText value={selected['endDate']} />],
              ['사유', String(selected['reason'] ?? '')],
              ['변경 근무시간', String(selected['changedWorkTime'] ?? '')],
              ['승인 처리 상태', <Badge value={selected['approvalStatus']} />],
            ]}
          />
        </section>
        {selected['approvalStatus'] === '신청' && (
          <section className="box">
            <h2>처리</h2>
            <button onClick={() => setCancelling(true)}>신청 취소</button>
          </section>
        )}
        {cancelling && (
          <Drawer title="근태 신청 취소" onClose={() => setCancelling(false)}>
            <Form
              onSubmit={submitCancel}
              submit="취소하기"
              danger
              note="취소하면 변경 이력이 남으며 되돌릴 수 없습니다. 승인된 신청은 취소할 수 없습니다."
            >
              <p>이 근태 신청을 취소합니다.</p>
            </Form>
          </Drawer>
        )}
      </div>
    );
  }

  const rows = data ? data.items : [];

  return (
    <div className="doc">
      <section className="box">
        <h2>근태 신청 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="근태 유형">
            <Select value={typeFilter} onChange={setTypeFilter} options={TYPE_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="승인 처리 상태">
            <Select value={statusFilter} onChange={setStatusFilter} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : undefined}>
          <button onClick={openCreate}>근태 신청</button>
        </Band>
        {error && <ErrorText text={error} />}
        <DataTable
          columns={[
            { key: 'attendanceType', label: '근태 유형' },
            { key: 'startDate', label: '시작일', render: (r: Row) => <DateText value={r['startDate']} /> },
            { key: 'endDate', label: '종료일', render: (r: Row) => <DateText value={r['endDate']} /> },
            { key: 'reason', label: '사유' },
            { key: 'approvalStatus', label: '승인 처리 상태', render: (r: Row) => <Badge value={r['approvalStatus']} /> },
          ]}
          rows={rows}
          onRowClick={(r: Row) => setSelected(r)}
          empty={loading ? '불러오는 중입니다.' : '아직 신청한 근태가 없습니다. 근태 신청 버튼을 눌러 등록해 주세요.'}
        />
        {data && <Pager page={data.page} size={data.size} total={data.total} onPage={setPage} />}
      </section>
      {creating && (
        <Drawer title="근태 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="신청하기">
            <Field label="근태 유형" required>
              <Select value={attendanceType} onChange={setAttendanceType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label="사유" wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            <Field label="변경 근무시간" hint="근무변경 신청일 때만 입력합니다.">
              <TextInput value={changedWorkTime} onChange={setChangedWorkTime} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
